"""Stress-size passive entries using external liquidity behind the fill price."""

from collections import deque
from math import ceil


class SweepCover:
    def __init__(self):
        self._flow = {}  # (instrument, exposed passive side) -> recent nonempty poll totals

    def observe(self, now, trade_ticks):
        for inst_id, trades in trade_ticks.items():
            totals = {'bid': 0, 'ask': 0}
            for trade in trades or ():
                side = str(getattr(trade, 'aggressor_side', '')).lower()
                if side in totals:
                    exposed = 'bid' if side == 'ask' else 'ask'
                    totals[exposed] += max(0, int(getattr(trade, 'volume', 0) or 0))
            for exposed, volume in totals.items():
                history = self._flow.setdefault((inst_id, exposed), deque(maxlen=64))
                while history and now - history[0][0] > 60.0:
                    history.popleft()
                if volume:
                    history.append((now, volume))

    def entry_lots(self, inst_id, side, price, tick, levels, inventory, approved):
        if approved <= 0 or tick <= 0 or side not in ('bid', 'ask'):
            return 0
        back = price - tick if side == 'bid' else price + tick
        depth = sum(max(0, int(lv.volume)) for lv in levels or ()
                    if abs(float(lv.price) - back) <= tick * 1e-6)
        volumes = sorted(v for _, v in self._flow.get((inst_id, side), ()))
        stress = volumes[ceil(0.90 * len(volumes)) - 1] if volumes else 1
        return min(approved, max(0, depth - stress - max(0, inventory)))

